<template><div><div class="page-header"><div><h1>成员管理</h1><p>查看和管理当前社区成员状态</p></div></div><ElCard class="panel-card" shadow="never"><div class="toolbar"><ElInput v-model="keyword" placeholder="搜索社区昵称" clearable @keyup.enter="search"/><ElSelect v-model="status" placeholder="全部状态" clearable><ElOption label="正常" value="ACTIVE"/><ElOption label="禁言" value="MUTED"/><ElOption label="封禁" value="BANNED"/><ElOption label="已离开" value="LEFT"/></ElSelect><ElButton type="primary" @click="search">查询</ElButton></div><ElTable v-loading="loading" :data="records"><ElTableColumn prop="memberId" label="成员 ID" width="100"/><ElTableColumn prop="displayName" label="社区昵称" min-width="140"/><ElTableColumn prop="username" label="登录账号" min-width="140"/><ElTableColumn label="角色" min-width="150"><template #default="scope"><ElTag v-for="role in scope.row.roles" :key="role" size="small">{{ role }}</ElTag></template></ElTableColumn><ElTableColumn label="状态" width="100"><template #default="scope"><ElTag :type="scope.row.status==='ACTIVE'?'success':'warning'">{{ scope.row.status }}</ElTag></template></ElTableColumn><ElTableColumn label="加入时间" min-width="180"><template #default="scope">{{ formatDate(scope.row.joinedAt) }}</template></ElTableColumn><ElTableColumn label="操作" width="150"><template #default="scope"><ElButton v-if="scope.row.status!=='ACTIVE'" link type="success" @click="changeStatus(scope.row,'ACTIVE')">恢复</ElButton><ElButton v-if="scope.row.status==='ACTIVE'" link type="danger" @click="changeStatus(scope.row,'BANNED')">封禁</ElButton></template></ElTableColumn></ElTable><ElPagination v-model:current-page="page" :page-size="20" :total="total" layout="total, prev, pager, next" @current-change="load"/></ElCard></div></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{getMembers,updateMemberStatus,type Member}from'@/api/merchant';const loading=ref(false),keyword=ref(''),status=ref(''),page=ref(1),total=ref(0),records=ref<Member[]>([]);const formatDate=(v:string)=>v?new Date(v).toLocaleString('zh-CN'):'-';async function load(){loading.value=true;try{const d=await getMembers({keyword:keyword.value||undefined,status:status.value||undefined,page:page.value,pageSize:20});records.value=d.records;total.value=d.total}catch{ElMessage.error('成员列表加载失败')}finally{loading.value=false}}function search(){page.value=1;load()}async function changeStatus(member:Member,next:string){await ElMessageBox.confirm(`确认将“${member.displayName}”状态修改为 ${next}？`,'成员状态',{type:'warning'});try{await updateMemberStatus(member.memberId,next);ElMessage.success('状态已更新');await load()}catch{ElMessage.error('状态更新失败')}}onMounted(load)</script>
<style scoped>.toolbar{display:flex;gap:12px;margin-bottom:18px}.toolbar .el-input{width:240px}.toolbar .el-select{width:160px}.el-pagination{justify-content:flex-end;margin-top:18px}.el-tag+.el-tag{margin-left:6px}</style>
